import React, { useEffect, useState } from "react";
import axios from "axios";
import { Spinner, Card, Button, Container, Row, Col, Alert } from "react-bootstrap";

const UpcomingEvents = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const token = localStorage.getItem("accessToken");
        if (!token) {
          setError("User not authenticated");
          return;
        }

        const response = await axios.get("http://localhost:8000/api/events/upcoming", {
          headers: { Authorization: `Bearer ${token}` },
        });

        console.log("📢 API Response:", response.data);
        setEvents(response.data);
      } catch (error) {
        console.error("❌ Error fetching events:", error.response?.data || error.message);
        setError(error.response?.data?.message || "Failed to fetch events");
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  // ✅ Register for an event
router.post('/:id/register', protect, async (req, res) => {
  try {
    const { id } = req.params;

    if (!id) {
      return res.status(400).json({ message: 'Event ID is required' });
    }

    const event = await Event.findById(id);

    if (!event) {
      return res.status(404).json({ message: 'Event not found' });
    }

    // ✅ Ensure the user is not already registered
    if (event.registeredUsers.includes(req.user._id)) {
      return res.status(400).json({ message: 'You have already registered for this event' });
    }

    event.registeredUsers.push(req.user._id);
    await event.save();

    const updatedEvent = await Event.findById(id).populate('registeredUsers', 'name email');

    res.status(200).json({
      message: 'Successfully registered for the event',
      event: updatedEvent,
    });
  } catch (error) {
    console.error('❌ Error registering for event:', error.message);
    res.status(500).json({ message: 'Failed to register for the event' });
  }
});


  // ✅ Unregister Event Function
  const handleUnregister = async (eventId) => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setError("User not authenticated");
        setTimeout(() => setError(""), 2000);
        return;
      }

      await axios.post(
        `http://localhost:8000/api/events/${eventId}/unregister`,
        {},
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      setMessage(`✅ Successfully unregistered from event!`);
      
      // ✅ UI update: registered state false kar do
      setEvents((prevEvents) =>
        prevEvents.map((event) =>
          event._id === eventId ? { ...event, isRegistered: false } : event
        )
      );

      setTimeout(() => setMessage(""), 2000);
    } catch (error) {
      setError(error.response?.data?.message || "Failed to unregister.");
      setTimeout(() => setError(""), 2000);
    }
  };

  return (
    <Container className="mt-5">
      <h2 className="text-center mb-4">Upcoming Events</h2>

      {loading && <Spinner animation="border" role="status" className="d-block mx-auto" />}
      {error && <Alert variant="danger" className="text-center">{error}</Alert>}
      {message && <Alert variant="success" className="text-center">{message}</Alert>}

      <Row>
        {events.length > 0 ? (
          events.map((event) => (
            <Col md={4} key={event._id} className="mb-4">
              <Card className="shadow-sm">
                <Card.Body>
                  <Card.Title>{event.title}</Card.Title>
                  <Card.Text>{event.description}</Card.Text>
                  <Card.Text>
                    📅 Date: <strong>{new Date(event.date).toLocaleDateString()}</strong>
                  </Card.Text>
                  {/* ✅ Conditional Button */}
                  {event.isRegistered ? (
                    <Button
                      variant="danger"
                      onClick={() => handleUnregister(event._id)}
                      className="me-2"
                    >
                      Unregister
                    </Button>
                  ) : (
                    <Button
                      variant="primary"
                      onClick={() => handleRegister(event._id)}
                      className="me-2"
                    >
                      Register
                    </Button>
                  )}
                </Card.Body>
              </Card>
            </Col>
          ))
        ) : (
          !loading && <p className="text-center">No upcoming events available.</p>
        )}
      </Row>
    </Container>
  );
};

export default UpcomingEvents;
